SELECT p.id AS position_id, w.signal_id, w.symbol, w.interval_code, w.candle_open_time, w.origin, w.status, w.attempts, w.updated_at, w.completed_at, w.paper_position_id, w.failure_stage, LEFT(w.error_message,300) AS err FROM paper_position p JOIN signal_processing_work w ON w.signal_id IN (p.signal_id, p.exit_signal_id) WHERE p.id IN (182,172,162,158,143,137) ORDER BY p.id, w.signal_id